'use strict';
const $=s=>document.querySelector(s),assets='/assets/';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(n,a)=>`<img src="/assets/${n}" alt="${a}">`;
const KEY='courtside-concept-v2';
window.courtsideSPA=true;
// GA4 key event after a successful send (public/analytics.js; a no-op until a measurement ID is set and the visitor allows it). No personal data.
function lead(type){try{window.courtsideAnalytics?.lead(type)}catch{}}
