const fresh=()=>({version:2,draft:{path:'group',step:1,weeks:[],players:'Not sure yet',partners:'Not sure yet',tennis:'Help us decide',party:'Solo',level:'Not sure yet',name:'',email:'',notes:''},group:null,requests:[],match:null,applications:[],hostApproved:false,hostPaid:false,suppliers:[{id:'hotel',title:'La Finca accommodation',detail:'Room mix + availability',status:'To request'},{id:'club',title:'Club de Tenis Almoradí',detail:'Courts + coaching schedule',status:'To request'},{id:'transport',title:'Ground transportation',detail:'Airport + club transfers',status:'To request'},{id:'support',title:'Trip support',detail:'Local lead + remote cover',status:'To request'}],tasks:[],activity:[],hostIdeas:[],hostTrip:'spain',hostStage:'before'});
let state;try{state=JSON.parse(localStorage.getItem(KEY)||'null')}catch{}if(!state||state.version!==2)state=fresh();
let tripPhase='Before travel';let tab='Overview',day=2,scheduleMode='personal',teamTab='Attention',hostTab='Overview',requestFilter='All',lastFocus=null;
function persist(){try{const {session,...kept}=state;localStorage.setItem(KEY,JSON.stringify(kept))}catch{toast('Browser storage is unavailable. Your progress will last for this visit only.')}}
// ---- Server wiring (CONCEPT02_PLAN.md, "Frontend contracts"). Every write goes through a same-origin JSON route.
const DEMO_KEY='courtside-demo';
// The query of the current hash route (#/invite?code=X), or of the page address when there is no hash route (/invite?code=X).
function query(){return new URLSearchParams(hashRoute()||location.hash.startsWith('#/?')?location.hash.split('?')[1]||'':location.search.slice(1))}
// The host / team / guide walkthrough views render only behind this flag: localStorage['courtside-demo']='1', set by any hash query carrying demo=1.
function demoOn(){try{if(query().get('demo')==='1')localStorage.setItem(DEMO_KEY,'1');return localStorage.getItem(DEMO_KEY)==='1'}catch{return false}}
const isDemoRoute=r=>r==='host-desk'||r==='operations'||r.startsWith('operations/')||r==='guide';
// POST JSON; resolves to { ok, status, data } and never throws (status 0 = network failure).
async function send(url,payload){try{const r=await fetch(url,{method:'POST',headers:{'content-type':'application/json',accept:'application/json'},body:JSON.stringify(payload)});let data=null;try{data=await r.json()}catch{}return{ok:r.ok,status:r.status,data}}catch{return{ok:false,status:0,data:null}}}
function submitButton(form){return form.querySelector('button:not([type]),button[type=submit]')}
function setBusy(form,label){form.setAttribute('aria-busy','true');form.querySelectorAll('button').forEach(b=>{b.disabled=true});const b=submitButton(form);if(b){b.dataset.label=b.innerHTML;b.textContent=label}}
function clearBusy(form){if(!form.isConnected)return;form.removeAttribute('aria-busy');form.querySelectorAll('button').forEach(b=>{b.disabled=false});const b=submitButton(form);if(b&&b.dataset.label!==undefined){b.innerHTML=b.dataset.label;delete b.dataset.label}}
function showError(form,text){const el=form.querySelector('.form-status');if(!el)return;el.textContent=text;el.classList.toggle('error',!!text)}
function errorText(r){if(r.status===400&&r.data?.errors&&typeof r.data.errors==='object')return Object.values(r.data.errors).join(' ');if(r.status===409&&r.data?.message)return r.data.message;if(r.status===429)return 'Too many attempts. Try again in a few minutes.';return 'Couldn’t reach Courtside. Try again.'}
const honeypot=()=>`<input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true">`;
const formStatus=(t='')=>`<p class="form-status${t?' error':''}" role="status" aria-live="polite">${esc(t)}</p>`;
const privacyLink=t=>`<a href="/privacy" target="_blank" rel="noopener">${t}</a>`;
function consentRow(id,text){return `<div class="consent-row"><input type="checkbox" id="${id}" name="consent" required><label for="${id}">${text}</label></div>`}
// The week options come from GET /api/lineup (the Weeks tab), fetched once per session when the request flow is entered.
let lineup=null,lineupError=false,lineupPromise=null,flowNotice='';
function loadLineup(force=false){if(lineup&&!force)return Promise.resolve(lineup);if(lineupPromise)return lineupPromise;lineupError=false;lineupPromise=fetch('/api/lineup',{headers:{accept:'application/json'}}).then(r=>{if(!r.ok)throw new Error(String(r.status));return r.json()}).then(data=>{lineup={trip:data.trip||{},weeks:Array.isArray(data.weeks)?data.weeks:[]};const ids=lineup.weeks.map(w=>w.weekId);state.weekLabels=Object.fromEntries(lineup.weeks.map(w=>[w.weekId,w.label]));state.draft.weeks=(state.draft.weeks||[]).map(w=>w==='Flexible'?'flexible':w).filter(w=>w==='flexible'||ids.includes(w));persist();return lineup}).catch(()=>{lineupError=true;return null}).finally(()=>{lineupPromise=null;if(route().startsWith('request/')&&state.draft.step===1)render()});return lineupPromise}
function weekLabel(id){if(id==='flexible'||id==='Flexible')return 'Flexible';return lineup?.weeks.find(w=>w.weekId===id)?.label||state.weekLabels?.[id]||id}
function weekOptions(d){if(lineupError)return `<div class="alert">Couldn’t load the weeks. <button type="button" class="plain" onclick="loadLineup(true)">Try again</button></div>`;if(!lineup)return `<p class="fieldhint" style="margin-top:22px">Loading weeks…</p>`;const closedTrip=lineup.trip.status&&lineup.trip.status!=='open';return `${closedTrip?`<div class="alert">${esc(lineup.trip.closedMessage||'Requests for this trip are closed.')}</div>`:''}<div class="options">${lineup.weeks.map(w=>{const closed=w.status!=='open';return `<label class="option ${closed?'disabled':''}"><input type="checkbox" name="week" value="${esc(w.weekId)}" ${d.weeks.includes(w.weekId)?'checked':''} ${closed?'disabled':''}>${esc(w.label)}<small>${closed?esc(w.closedMessage||'Requests for this week are closed.'):'Available to request · 2027'}</small></label>`}).join('')}</div>`}
let autoCode='';
async function submitInvite(e){e.preventDefault();const f=e.target,code=f.elements.code.value.trim().toUpperCase();if(!code)return;showError(f,'');setBusy(f,'Checking…');const r=await send('/api/code',{code,website:f.elements.website?.value||''});if(r.ok){state.invite={code,invitedBy:r.data?.invitedBy||'',issuedTo:r.data?.issuedTo||''};persist();clearBusy(f);go('trip');return}clearBusy(f);if(r.status===401){state.inviteReason=r.data?.reason||'invalid';persist();go('invite-unavailable');return}showError(f,errorText(r))}
async function submitWaitlist(e,source='concept02-waitlist',interest){e.preventDefault();const f=e.target,el=f.elements;showError(f,'');setBusy(f,'Sending…');const r=await send('/api/waitlist',{email:(el.email?.value||'').trim(),name:(el.name?.value||'').trim(),interest:interest||el.interest?.value||'',source,consent:true,website:el.website?.value||''});if(r.ok){state.waitlisted=true;persist();clearBusy(f);lead('waitlist');go('waitlist-done');return}clearBusy(f);showError(f,errorText(r))}
function submitHomeWaitlist(e){return submitWaitlist(e,'concept02-home','Future Courtside experiences')}
// ---- Routing. The public, indexable pages have real addresses (scripts/make-pages.js writes one HTML file per path, so a
// crawler gets each page's own head and summary); every other view is a hash route (#/start, #/group, #/join/…), which
// keeps personal links out of search. A non-empty hash route wins; otherwise the view is the one for location.pathname.
const PUBLIC_PATHS={'':'/','trips':'/trips','trip':'/trips/spanish-offseason','host':'/hosts/katie','about':'/about','apply':'/apply','invite':'/invite'};
const PATH_ROUTES=Object.fromEntries(Object.entries(PUBLIC_PATHS).map(([r,p])=>[p,r]));
// Old shared links to these hash routes move to the real address (#/invite stays: personal links carry ?code=).
const LEGACY_HASH=['trip','trips','host','about','apply'];
const PAGE_TITLES={'':'Courtside Travel Co. — Hosted tennis trips with your pro','trips':'Hosted tennis trips — Courtside Travel Co.','trip':'The Spanish Offseason — a hosted tennis week in Spain | Courtside Travel Co.','host':'Katie Delich, your host — Courtside Travel Co.','about':'About Courtside Travel Co. — travel with your pro','apply':'Host a trip with Courtside — for tennis pros','invite':'Enter your invitation — Courtside Travel Co.'};
const cleanPath=p=>{p=String(p||'/').replace(/\.html$/,'').replace(/\/+$/,'')||'/';return p==='/index'?'/':p};
function hashRoute(){return location.hash.startsWith('#/')?location.hash.slice(2).split('?')[0]:''}
function route(){return hashRoute()||PATH_ROUTES[cleanPath(location.pathname)]||''}
const hrefFor=p=>PUBLIC_PATHS[p]??'#/'+p;
// Same-document navigation: push (or replace) the address, then render it.
function navigate(url,replace=false){history[replace?'replaceState':'pushState'](null,'',url);onNav()}
function go(p){const path=PUBLIC_PATHS[p];if(path!==undefined){if(!hashRoute()&&cleanPath(location.pathname)===path){render();window.scrollTo(0,0)}else navigate(path);return}
if(route()===p){render();window.scrollTo(0,0)}else if(location.pathname==='/')location.hash='/'+p;else navigate('/#/'+p)}
// The route name analytics may see: the public path, or the hash route without ids (never CSM-/CSG-/CS- ids, codes or emails).
function analyticsPath(){const h=hashRoute();if(!h)return cleanPath(location.pathname);const [a,b]=h.split('/');return '/#/'+(a==='request'&&(b==='group'||b==='match')?a+'/'+b:a==='help'&&b==='new'?'help/new':a)}
let shownUrl='';
// Runs on load and on every address change (popstate, hashchange, navigate()); renders once per distinct address.
function onNav(initial=false){const h=hashRoute();if(LEGACY_HASH.includes(h)){demoOn();history.replaceState(null,'',PUBLIC_PATHS[h])}else if(location.hash==='#/'&&!h)history.replaceState(null,'',location.pathname+location.search);
const url=location.pathname+location.search+location.hash;if(url===shownUrl)return;shownUrl=url;clearTimeout(autosave);render();if(!initial){window.scrollTo(0,0);$('#main').focus({preventScroll:true})}
try{window.courtsideAnalytics?.pageView(analyticsPath(),document.title)}catch{}}
// Links to the public pages (and to hash routes from a public page) stay in this document: same-origin, plain left clicks only.
document.addEventListener('click',e=>{if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const a=e.target.closest?.('a[href]');if(!a||(a.target&&a.target!=='_self')||a.hasAttribute('download'))return;let url;try{url=new URL(a.href,location.href)}catch{return}if(url.origin!==location.origin)return;
if(url.hash.startsWith('#/')&&url.hash.length>2){if(url.pathname!==location.pathname&&url.pathname!=='/')return;if(location.pathname==='/'&&url.pathname==='/')return;e.preventDefault();navigate('/'+url.hash);return}
const r=PATH_ROUTES[cleanPath(url.pathname)];if(r===undefined||(url.hash&&!url.hash.startsWith('#/')))return;e.preventDefault();if(url.pathname+url.search===location.pathname+location.search&&!hashRoute()){go(r);return}navigate(cleanPath(url.pathname)+url.search)});
function toast(s){const t=document.createElement('div');t.className='toast';t.textContent=s;$('#live').textContent=s;document.body.append(t);setTimeout(()=>t.remove(),4200)}
function stamp(){return new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}
function log(s){state.activity.unshift({text:s,time:stamp()});state.activity=state.activity.slice(0,30)}
function uid(prefix){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6)}
function badge(s,type=''){return `<span class="badge ${type}">${esc(s)}</span>`}
function link(p,t,cls='btn'){return `<a class="${cls}" href="${hrefFor(p)}">${t}</a>`}
function select(name,values,val,extra=''){return `<select name="${name}" ${extra}>${values.map(v=>`<option value="${esc(v)}" ${v===val?'selected':''}>${esc(v)}</option>`).join('')}</select>`}
function field(name,label,value='',type='text',required=false,placeholder=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} placeholder="${esc(placeholder)}"></label>`}
function note(t='Interactive concept. Sample data stays in this browser. No messages, payments or bookings are sent.'){return `<div class="demo-note">${t}</div>`}
function aside(){return `<aside class="flow-aside card"><div class="card-image">${img('coast.jpg','Katie and Eva together in Spain')}</div><div class="cardbody"><div class="eyebrow">TRAVEL WITH KATIE + EVA</div><h3>The Spanish Offseason</h3><p class="muted small">Six nights on the Costa Blanca.<br>Tennis together. Room for your own pace.</p><div class="divider"></div><p class="small">From $2,995 per player<br><span class="muted">Shared-room starting estimate.</span></p><p class="small muted">Courtside handles the planning, coordination and support.</p></div></aside>`}
// The demo-flag screens' contact panel; public screens use guestPanel().
function supportPanel(){return `<aside><section class="panel"><div class="eyebrow">YOUR COURTSIDE CONTACT</div><h3>We’ve got<br>the details.</h3><p class="muted small">Jeffery · sample trip lead<br>Local support · assignment to confirm</p><p class="small muted">Your hosts enjoy the week with you. Courtside handles arrangements, changes and questions.</p><div class="actions"><button class="btn full" onclick="hostQuestion()">Contact the trip lead ↗</button></div></section><div class="demo-note">Support channels and staffed hours would be confirmed before travel. This prototype does not provide live assistance.</div></aside>`}
function shell(title,eyebrow,body,subtitle='',actions=''){return `<section class="workspace"><div class="workspace-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${subtitle?`<p class="muted small">${subtitle}</p>`:''}</div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>${body}</section>`}
